// data/sfx.js
// Efectos de sonido cortos embebidos en base64.
//
// Bajo file:// (doble clic en index.html), fetch() está bloqueado por el
// navegador para el esquema "file" (a diferencia de <audio src="file://...">,
// que sí funciona). js/sounds.js cargaba estos 7 efectos cortos con fetch()
// para decodificarlos vía Web Audio API, así que bajo file:// la petición
// fallaba en silencio y nunca se oía ningún efecto. Aquí van embebidos como
// base64 para que sounds.js los decodifique directamente, sin red de por medio.
// bgm.mp3 y victory.mp3 se excluyen a propósito (varios MB cada uno: no vale
// la pena embeberlos en base64) y siguen sonando vía <audio>, que sí funciona
// bajo file://.
window.TT_SFX = {
  select: "",
  flip: "",
  place: "",
  error: "",
  spin: "",
  back: "",
  success: ""
};
